#include <stdio.h>
int main() {
    int age;
    printf("Enter your age: ");
    scanf("%d", &age);
    printf("You are %d years old.\n", age);
    return 0;
}

#include <stdio.h>
int main() {
    char name[20];
    float height;
    printf("Enter name and height (e.g., John 1.75): ");
    scanf("%s %f", name, &height);
    printf("Name: %s, Height: %.2f meters\n", name, height);
    return 0;
}

