#include <stdio.h>
int main() {
    int num = 10;
    float pi = 3.14159;
    char grade = 'A';
    printf("Number: %d, PI: %f, Grade: %c\n", num, pi, grade);
    return 0;
}

#include <stdio.h>
int main() {
    float value = 123.45678;
    int count = 5;
    printf("Value (2 decimal places): %.2f\n", value);
    printf("Value (total width 10, 2 dec): %10.2f\n", value);
    printf("Count (padded with spaces): %5d\n", count);
    return 0;
}
